using System.Buffers.Binary;
using System.Security.Cryptography;
using S7Patcher.Source;

int passed = 0;
void Check(bool condition, string message) { if (!condition) throw new Exception(message); passed++; }
static void Length(byte[] packet)
{
    if (packet.Length >= 4) BinaryPrimitives.WriteUInt32LittleEndian(packet, (uint)(packet.Length - 4));
}
// Fixed vectors transcribed from the static field layout, not generated by the
// codec. IDs, profile bytes, one-character URL and body are invented test data.
byte[] login = Convert.FromHexString("3b0000000e004c6f67696e50726f746f636f6c00017856341221004c6f67696e50726f746f636f6c3a3a4c6f67696e57697468546f6b656e5f56310000ff7f");
byte[] register = Convert.FromHexString("320000000e004c6f67696e50726f746f636f6c0001785634121b004c6f67696e50726f746f636f6c3a3a52656769737465725f563100");
byte[] loginResponse = Convert.FromHexString("4f0000000e004c6f67696e50726f746f636f6c0000017856341222004c6f67696e50726f746f636f6c3a3a4c6f67696e57697468546f6b656e5f56312a00000102030405060708090a0b0c0d0e0f0200780000");
byte[] registerResponse = Convert.FromHexString("3c0000000e004c6f67696e50726f746f636f6c000001785634121c004c6f67696e50726f746f636f6c3a3a52656769737465725f56312a004433221102007800");
byte[] before = SHA256.HashData(login);
Check(LoginRpcCodec.TryReadRequest(login, out var parsed, out var failure) && failure == LoginRpcFailure.None, "Fixed login request not recognized");
Check(parsed.Method == LoginRpcMethod.LoginWithTokenV1 && parsed.CallId == 0x12345678 && parsed.BodyOffset == 60 && parsed.BodyLength == 3, "Login header/body boundary incorrect");
Check(login.AsSpan(parsed.BodyOffset).SequenceEqual(new byte[] { 0, 255, 127 }), "Opaque arguments changed");
Check(SHA256.HashData(login).SequenceEqual(before), "Request input mutated");
Check(LoginRpcCodec.TryReadRequest(register, out var registerHeader, out _) && registerHeader.Method == LoginRpcMethod.RegisterV1
    && registerHeader.BodyOffset == 54 && registerHeader.BodyLength == 0, "Register header not recognized independently of arguments");
Check(!parsed.ToString()!.Contains("305419896"), "Header ToString exposes opaque call ID");

void Reject(byte[] packet, LoginRpcFailure? expected = null)
{
    Check(!LoginRpcCodec.TryReadRequest(packet, out var header, out var error)
        && header.Method == LoginRpcMethod.Unknown && header.CallId == 0 && header.BodyLength == 0
        && error != LoginRpcFailure.None && (expected == null || expected == error), "Malformed request accepted or retained partial metadata");
}
for (int length = 0; length < 60; length++)
{
    byte[] truncated = login[..length]; Length(truncated); Reject(truncated);
}
for (int removed = 0; removed <= 3; removed++)
{
    byte[] shorterBody = login[..(login.Length - removed)]; Length(shorterBody);
    Check(LoginRpcCodec.TryReadRequest(shorterBody, out var header, out _) && header.BodyLength == 3 - removed, "Codec interpreted opaque body as required arguments");
}
foreach (uint declared in new uint[] { 0, 58, 60, uint.MaxValue })
{
    byte[] bad = (byte[])login.Clone(); BinaryPrimitives.WriteUInt32LittleEndian(bad, declared); Reject(bad, LoginRpcFailure.OuterLengthMismatch);
}
Reject([.. login, 0], LoginRpcFailure.OuterLengthMismatch);
foreach (ushort length in new ushort[] { 0, 255, 256, ushort.MaxValue })
{
    byte[] bad = (byte[])login.Clone(); BinaryPrimitives.WriteUInt16LittleEndian(bad.AsSpan(4), length); Reject(bad);
    bad = (byte[])login.Clone(); BinaryPrimitives.WriteUInt16LittleEndian(bad.AsSpan(25), length); Reject(bad);
}
foreach (int offset in new[] { 6, 18, 27, 40 })
{
    foreach (byte value in new byte[] { 0, 0x1f, 0x80, 0xff })
    { byte[] bad = (byte[])login.Clone(); bad[offset] = value; Reject(bad, LoginRpcFailure.InvalidString); }
}
foreach (int offset in new[] { 19, 59 })
{ byte[] bad = (byte[])login.Clone(); bad[offset] = (byte)'x'; Reject(bad, LoginRpcFailure.InvalidString); }
foreach (byte flag in new byte[] { 0, 2, 255 })
{ byte[] bad = (byte[])login.Clone(); bad[20] = flag; Reject(bad, LoginRpcFailure.UnexpectedRequestFlag); }
byte[] unknown = (byte[])login.Clone(); unknown[6] = (byte)'X'; Reject(unknown, LoginRpcFailure.UnknownProtocol);
unknown = (byte[])login.Clone(); unknown[27] = (byte)'X'; Reject(unknown, LoginRpcFailure.UnknownMethod);
Reject(loginResponse, LoginRpcFailure.UnexpectedRequestFlag);
Reject(registerResponse, LoginRpcFailure.UnexpectedRequestFlag);
byte[] maximum = new byte[LoginRpcCodec.MaximumMessageLength]; login.CopyTo(maximum, 0); Length(maximum);
Check(LoginRpcCodec.TryReadRequest(maximum, out var maxHeader, out _) && maxHeader.BodyLength == maximum.Length - 60, "Exact local message limit rejected");
Reject(new byte[LoginRpcCodec.MaximumMessageLength + 1], LoginRpcFailure.LimitExceeded);

byte[] profile = Enumerable.Range(0, 16).Select(value => (byte)value).ToArray();
Check(LoginRpcCodec.TryWriteLoginSuccess(0x12345678, new(profile, "x", false), out byte[] encodedLogin, out failure)
    && failure == LoginRpcFailure.None && encodedLogin.SequenceEqual(loginResponse), "Fixed Login success envelope/return vector differs");
Check(LoginRpcCodec.TryWriteRegisterSuccess(0x12345678, new(0x11223344, "x"), out byte[] encodedRegister, out failure)
    && encodedRegister.SequenceEqual(registerResponse), "Fixed Register success envelope/return vector differs");
Check(profile.SequenceEqual(Enumerable.Range(0, 16).Select(value => (byte)value)), "Raw ProfileID input mutated");
Check(LoginRpcCodec.TryWriteLoginSuccess(uint.MaxValue, new(profile, "", true), out byte[] redirected, out _)
    && redirected[^1] == 1 && redirected[^2] == 0 && BinaryPrimitives.ReadUInt16LittleEndian(redirected.AsSpan(redirected.Length - 4)) == 1
    && BinaryPrimitives.ReadUInt32LittleEndian(redirected.AsSpan(22)) == uint.MaxValue, "Redirect flag, empty nonnull string or call ID boundary incorrect");
Check(LoginRpcCodec.TryWriteRegisterSuccess(0, new(uint.MaxValue, ""), out byte[] maxId, out _)
    && BinaryPrimitives.ReadUInt32LittleEndian(maxId.AsSpan(56)) == uint.MaxValue, "RVCID is not raw u32LE");
foreach (int length in new[] { 0, 15, 17 })
    Check(!LoginRpcCodec.TryWriteLoginSuccess(0, new(new byte[length], "x", false), out byte[] output, out failure)
        && output == null && failure == LoginRpcFailure.InvalidProfileIdLength, "Invalid ProfileID length accepted");
foreach (string text in new string[] { null, "bad\0value", "bad\nvalue", "bad\u007fvalue", "ü", "\ud800" })
{
    Check(!LoginRpcCodec.TryWriteLoginSuccess(0, new(profile, text, false), out byte[] output, out failure)
        && output == null && failure == LoginRpcFailure.InvalidString, "Invalid Login StationURL string accepted");
    Check(!LoginRpcCodec.TryWriteRegisterSuccess(0, new(1, text), out output, out failure)
        && output == null && failure == LoginRpcFailure.InvalidString, "Invalid Register StationURL string accepted");
}
foreach (int length in new[] { 65535, 65536, 100000 })
    Check(!LoginRpcCodec.TryWriteRegisterSuccess(0, new(1, new string('x', length)), out byte[] output, out failure)
        && output == null && failure == LoginRpcFailure.LimitExceeded, "String length overflow/clamping accepted");
int maximumLoginUrl = LoginRpcCodec.MaximumMessageLength - (loginResponse.Length - 1);
Check(LoginRpcCodec.TryWriteLoginSuccess(0, new(profile, new string('x', maximumLoginUrl), false), out byte[] maxReply, out _)
    && maxReply.Length == LoginRpcCodec.MaximumMessageLength && BinaryPrimitives.ReadUInt32LittleEndian(maxReply) == 65532, "Response limit rejected or outer length wrong");
Check(!LoginRpcCodec.TryWriteLoginSuccess(0, new(profile, new string('x', maximumLoginUrl + 1), false), out _, out failure)
    && failure == LoginRpcFailure.LimitExceeded, "Response exceeded total message cap");

Random random = new(20261025);
for (int iteration = 0; iteration < 10000; iteration++)
{
    byte[] sample = new byte[random.Next(0, 500)]; random.NextBytes(sample);
    if ((iteration & 1) == 0) Length(sample);
    bool accepted = LoginRpcCodec.TryReadRequest(sample, out var header, out _);
    Check(!accepted || (header.BodyOffset >= 4 && header.BodyLength >= 0 && header.BodyOffset + header.BodyLength == sample.Length), "Random input escaped bounds");
}
Console.WriteLine($"PASS: {passed} isolated RPC codec checks; fixed vectors, bounds, malformed headers, opaque bodies, response types and 10000 random inputs. No network or game integration.");
